    "když": ["Když prší, jsem doma.","When it rains, I stay home."],
    "jako": ["Mluvíte jako Čech.","You speak like a Czech."],
    "nebo": ["Kávu, nebo čaj?","Coffee or tea?"],
    "protože": ["Nejdu, protože jsem nemocný.","I'm not going, because I'm sick. (a man)"],
    "aby": ["Mluvte pomalu, abych rozuměl.","Speak slowly so that I understand. (a man)"],
    "než": ["Praha je větší než Brno.","Prague is bigger than Brno."],
    "jestli": ["Nevím, jestli přijdu.","I don't know if I'll come."],
    "i": ["Mám rád čaj i kávu.","I like both tea and coffee. (a man)"],
    "takže": ["Prší, takže jedu autobusem.","It's raining, so I'm taking the bus."],
    "ani": ["Nemám čas ani peníze.","I have neither time nor money."],
    "až": ["Zavolám, až budu doma.","I'll call when I'm home."],
    "pokud": ["Pokud máte čas, přijďte.","If you have time, come."],
    "kdyby": ["Kdybych měl čas, přišel bych.","If I had time, I would come. (a man)"],
    "proto": ["Jsem nemocná, proto nejdu.","I'm sick, that's why I'm not going. (a woman)"],
    "dokud": ["Počkám, dokud nepřijdete.","I'll wait until you come."],
    "však": ["To je však drahé.","That is, however, expensive."],
    "jakmile": ["Zavolám, jakmile přijedu.","I'll call as soon as I arrive."],
    "přestože": ["Přestože prší, jdu ven.","Although it's raining, I'm going out."],
    "i když": ["Jdu ven, i když prší.","I'm going out, even though it's raining."],
    "buď": ["Buď dnes, nebo zítra.","Either today or tomorrow."],
    "čas": ["Nemám čas.","I don't have time."],
    "pravda": ["Máte pravdu.","You're right."],
    "peníze": ["Nemám peníze.","I don't have money."],
    "dveře": ["Zavřete dveře, prosím.","Close the door, please."],
    "hlad": ["Mám hlad.","I'm hungry."],
