    "dárek": ["To je dárek pro vás.","This is a present for you."],
    "odpověď": ["To je dobrá odpověď.","That's a good answer."],
    "chyba": ["To je moje chyba.","That's my fault."],
    "kolik": ["Kolik je vám let?","How old are you?"],
    "odkud": ["Odkud jste?","Where are you from?"],
